void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
template<class Work>void reject(Work work){bool failed=false;try{work();}catch(...){failed=true;}check(failed,"Expected rejection");}
auto deadline(){return std::chrono::steady_clock::now()+std::chrono::seconds(30);}
Invocation capture(const Document& d,std::string mse="null"){
 InvocationCapture c(d,std::move(mse));while(!c.advance(d,deadline())){}return c.take();
}
Document fixture(int size,int frames,bool linked){
 timeline::State state;timeline::Layer layer;layer.id="layer";layer.name=U"图层🌙";state.layers.push_back(layer);
 for(int i=0;i<frames;++i){const auto id="frame-"+std::to_string(i);state.frames.push_back({id,100,false});timeline::Cel cel;cel.id="cel-"+std::to_string(i);cel.layerId=layer.id;cel.frameId=id;
  if(linked&&i)cel.linkedCelId="cel-0";else{timeline::Surface s;s.width=s.height=size;s.offsetX=-2;s.offsetY=3;s.storageOriginX=-4;s.storageOriginY=5;s.pixels.resize(std::size_t(size)*size);s.pixels[0]=0x00123456;s.pixels.back()=0xffabcdef;cel.surface=std::move(s);}state.cels.push_back(std::move(cel));
 }
 return Document::fromImported(size,size,std::move(state),PaletteState{},"project",U"工程🌙",std::make_shared<const std::vector<std::uint8_t>>());
}
void dialogStateTests(Runtime& runtime,const std::filesystem::path& root){
 // Native window draft/action state against a dialog produced by real Lua.
 {std::ofstream file(root/"scripts"/"controls.lua");file<<"local d=Dialog('Controls'); d:entry{id='name',text='old'}; d:number{id='n',text='3'}; d:slider{id='s',min=1,max=10,value=4}; d:check{id='check',selected=false}; d:radio{id='r1',selected=true}; d:radio{id='r2',selected=false}; d:separator{}; d:radio{id='r3',selected=true}; d:combobox{id='choice',options={'a','b'},option='a'}; d:color{id='color',color=Color{r=1,g=2,b=3,a=4}}; d:label{text='hello'}; d:button{id='apply',text='Apply',onclick=function() print(d.data.name) end}; d:show{wait=false}";file.close();auto edited=std::make_unique<Document>(fixture(3,1,false));auto first=JsonObject::Parse(winrt::to_hstring(runtime.startInvocation("controls.lua",capture(*edited)).get()));const auto session=winrt::to_string(first.GetNamedString(L"sessionId"));auto dialog=first.GetNamedArray(L"dialogs").GetObjectAt(0);DialogState state(winrt::to_string(dialog.Stringify()));
  check(state.edit("name",R"("draft")")&&!state.commit("name",DialogState::Commit::PointerUp)&&state.commit("name",DialogState::Commit::Enter).has_value(),"Entry draft/Enter wrong");check(!state.edit("name","42")&&!state.edit("name",R"("busy")",true),"Entry invalid/busy edit accepted");
  check(state.edit("n","8")&&!state.commit("n",DialogState::Commit::Enter)&&state.commit("n",DialogState::Commit::Blur).has_value(),"Number commit wrong");check(state.edit("s","7")&&state.commit("s",DialogState::Commit::PointerUp).has_value()&&!state.commit("s",DialogState::Commit::Change),"Slider release wrong");
  check(state.edit("check","true")&&state.click("check").has_value()&&!state.click("check",true),"Check click/busy wrong");check(state.click("r2").has_value(),"Radio click missing");auto values=JsonObject::Parse(winrt::to_hstring(state.valuesJson()));check(!values.GetNamedBoolean(L"r1")&&values.GetNamedBoolean(L"r2")&&values.GetNamedBoolean(L"r3"),"Radio grouping crossed separator");
  check(state.edit("choice",R"("b")")&&state.commit("choice",DialogState::Commit::Change).has_value(),"Combobox change wrong");check(state.edit("color",R"({"r":9,"g":8,"b":7,"a":6})")&&!state.edit("color",R"({"r":9})")&&state.commit("color",DialogState::Commit::Change).has_value(),"Color change wrong");
  auto click=state.click("apply");check(click.has_value(),"Button action missing");auto result=JsonObject::Parse(winrt::to_hstring(runtime.dispatchInvocation(session,*click,capture(*edited)).get()));check(result.GetNamedArray(L"output").GetStringAt(0)==L"draft","Action lost uncommitted draft values");
  auto close=JsonObject::Parse(winrt::to_hstring(state.close()));check(close.GetNamedValue(L"controlId").ValueType()==JsonValueType::Null&&close.GetNamedObject(L"values").GetNamedString(L"name")==L"draft","Window close lost drafts");state.reset(winrt::to_string(dialog.Stringify()));check(JsonObject::Parse(winrt::to_hstring(state.valuesJson())).GetNamedString(L"name")==L"old","Returned dialog did not reset drafts");
  auto modified=JsonObject::Parse(dialog.Stringify());for(const auto& item:modified.GetNamedArray(L"controls")){auto c=item.GetObject();if(c.GetNamedString(L"id")==L"r1"){c.Insert(L"visible",JsonValue::CreateBooleanValue(false));c.Insert(L"enabled",JsonValue::CreateBooleanValue(false));}if(c.GetNamedString(L"id")==L"name")c.Insert(L"enabled",JsonValue::CreateBooleanValue(false));}
  state.reset(winrt::to_string(modified.Stringify()));check(!state.click("r1")&&!state.edit("name",R"("ignored")")&&!state.commit("name",DialogState::Commit::Enter),"Hidden/disabled controls accepted action");check(state.click("r2").has_value()&&!JsonObject::Parse(winrt::to_hstring(state.valuesJson())).GetNamedBoolean(L"r1"),"Hidden radio peer not cleared");runtime.close(session).get();
 }
}
void clientDialogTests(Runtime& runtime,const std::filesystem::path& root){

 std::ofstream file(root/"scripts"/"client-drafts.lua");file<<"local a; a=Dialog{title='First',onclose=function() print('close:'..a.data.name) end}; a:entry{id='name',text='first'}; a:button{id='apply',text='Apply',onclick=function() print(a.data.name); a:modify{id='name',text='reset'} end}; a:show{wait=false}; local b; b=Dialog{title='Second',onclose=function() print('close:'..b.data.name) end}; b:entry{id='name',text='second'}; b:button{id='apply',text='Apply',onclick=function() print(b.data.name) end}; b:show{wait=false}";file.close();
 auto edited=std::make_unique<Document>(fixture(3,1,false));Client client(runtime);
 auto pump=[&]{const auto end=deadline();while(client.running()&&std::chrono::steady_clock::now()<end){client.tick(edited.get(),deadline());std::this_thread::yield();}check(!client.running()&&client.error().empty(),"Client draft operation failed");};
 client.run(edited.get(),"client-drafts.lua","null");pump();check(client.session().has_value(),"Draft client has no session");auto models=JsonArray::Parse(winrt::to_hstring(client.session()->dialogsJson));check(models.Size()==2,"Multiple dialog creation failed");auto first=winrt::to_string(models.GetObjectAt(0).GetNamedString(L"id")),second=winrt::to_string(models.GetObjectAt(1).GetNamedString(L"id"));
 check(client.editDialog(first,"name",R"("local first")")&&client.editDialog(second,"name",R"("local second")"),"Client draft editing failed");check(!client.editDialog("missing","name",R"("ignored")"),"Unknown dialog edited");
 check(client.clickDialog(edited.get(),first,"apply","null"),"Draft button did not dispatch");check(!client.editDialog(second,"name",R"("busy")")&&!client.clickDialog(edited.get(),second,"apply","null"),"Busy window accepted edits/actions");pump();check(client.report()&&client.report()->output==std::vector<std::string>{"local first"},"Button did not send local draft");check(client.dialog(first)&&JsonObject::Parse(winrt::to_hstring(client.dialog(first)->valuesJson())).GetNamedString(L"name")==L"reset","Callback modify did not replace draft");check(JsonObject::Parse(winrt::to_hstring(client.dialog(second)->valuesJson())).GetNamedString(L"name")==L"second","Callback did not reset other window draft");
 client.dismissReport();check(client.editDialog(second,"name",R"("title draft")")&&client.closeDialog(edited.get(),second,"null"),"Window close not dispatched");pump();check(client.report()&&client.report()->output==std::vector<std::string>{"close:title draft"}&&!client.dialog(second)&&client.dialog(first),"Window close lost drafts or retained window");client.dismissReport();
 check(client.editDialog(first,"name",R"("enter draft")")&&client.commitDialog(edited.get(),first,"name",DialogState::Commit::Enter,"null"),"Client entry commit failed");pump();
 // App-level Escape deliberately sends the returned model, matching legacy
 // useAppScriptRuntime, rather than the title-close local value path.
 check(client.editDialog(first,"name",R"("escape draft")")&&client.closeTopDialog(edited.get(),"null"),"App Escape did not dispatch");pump();check(!client.session()&&!client.dialog(first)&&client.report()&&client.report()->output==std::vector<std::string>{"close:enter draft"},"Escape model-values behavior changed");
 client.dismissReport();client.run(edited.get(),"client-drafts.lua","null");pump();models=JsonArray::Parse(winrt::to_hstring(client.session()->dialogsJson));first=winrt::to_string(models.GetObjectAt(0).GetNamedString(L"id"));client.observe(nullptr);check(!client.dialog(first)&&!client.busy(),"Workspace change retained window drafts");
}
